    if not junctions or len({j.source_id for j in junctions})!=len(junctions):
        raise ValueError('Physical junction IDs must be distinct')
    origin=tuple(origin)+(0.,)*(3-len(origin));streets={}
    for junction in junctions:
        if len(junction.connectors)<3:raise ValueError('A physical junction needs at least three incidences')
        for street in junction.streets:
            if streets.setdefault(street.source_id,street)!=street:
                raise ValueError('Original Street differs between its physical owners')
    vertices=[];edges=[];widths=[];offsets=[];sids=[];street_ids=[]
    section_vertices={};section_edges={};street_vertices={}
